import django.db.models.deletion
import re

from django.db import migrations, models


def popola_catalogo(apps, schema_editor):
    """Una competenza del catalogo per ogni nome usato dalle voci di mansione (stesso nome = stessa competenza)."""
    Voce = apps.get_model("anagrafica", "VoceMacchinaCatalogo")
    Catalogo = apps.get_model("anagrafica", "CompetenzaCatalogo")
    per_chiave = {}
    for voce in Voce.objects.filter(mansione__isnull=False).order_by("-attiva", "pk"):
        nome = " ".join((voce.nome or "").split())[:150]
        k = re.sub(r"\s+", " ", nome).casefold()[:160]
        if not k:
            continue
        cat = per_chiave.get(k)
        if cat is None:
            cat = Catalogo.objects.filter(chiave=k).first() or Catalogo.objects.create(nome=nome, chiave=k)
            per_chiave[k] = cat
        voce.catalogo_id = cat.pk
        voce.save(update_fields=["catalogo"])


